const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={saved:[],custom:[],sessions:0};try{Object.assign(state,JSON.parse(localStorage.getItem('qixin-flow-v1')||'{}'))}catch{}function persist(){try{localStorage.setItem('qixin-flow-v1',JSON.stringify(state))}catch{toast('本机存储不可用，当前页面仍可继续体验')}}
const INTRO='找到一个舒服的姿势。你可以闭上眼睛，也可以让目光轻轻停在前方。随时可以暂停练习。呼吸保持自然，不必勉强。';const OUTRO='慢慢感受身体与周围的空间。动一动手指，留意房间里的声音。当你准备好了，把这份温柔带回今天。';
const practices=[{id:'rest',title:'把今天的疲惫，轻轻放下',tag:'日常放松',category:'focus',minutes:5,art:0,source:'original',paragraphs:[INTRO,'感受身体被座椅稳稳承托。把肩膀放低一点，让下颌也松开。此刻，你可以暂时不用回应世界。','留意空气经过鼻尖时的感觉。每次呼气，都给自己留一点空间。不必刻意深呼吸，跟随自然的节奏就好。','今天做完或没有做完的事情，可以先放到一旁。你不需要在这几分钟里解决它们。','如果思绪走远，温柔地说一句：我注意到了。再把注意力放回身体与呼吸。','问问自己，现在有什么简单的需要？一杯水、短暂休息，或一句表达。允许自己认真对待这个需要。',OUTRO]},
{id:'sleep',title:'今晚，安心睡个好觉',tag:'睡前陪伴',category:'sleep',minutes:5,art:1,source:'original',paragraphs:[INTRO,'感受床铺承托身体的重量。留意头部、背部和腿部与床面的接触。不必立刻入睡，只是允许休息。','放松眼周和脸颊，让双手自然放在舒服的位置。留意每一次呼吸都在发生。','如果白天的念头出现，对它们说：我看见你们了，明天再来照顾。此刻先陪着自己的身体。','从脚趾到脚踝，慢慢留意身体的感觉。哪里紧绷，就给那里多一点温柔，不必强迫它放松。','允许清醒，也允许困倦。你不需要和任何一种状态对抗。接下来的时间，只是安静地休息。',OUTRO]},
{id:'kind',title:'你值得，被自己好好爱着',tag:'自我关怀',category:'self',minutes:3,art:2,source:'original',paragraphs:[INTRO,'留意此刻心里的感受。不急着给它名字，也不用判断它应该或不应该存在。','如果愿意，把手轻放在胸口。感受手掌的温度，感受身体仍在认真地陪伴你。','试着对自己说：这些感受都可以被看见。我不必完美，才值得被善待。','想一想，如果最亲近的人有同样的感受，你会如何回应？试着把那句话，也送给自己。','为自己选择一件温柔的小事。它可以很小，却同样值得。',OUTRO]},
{id:'focus',title:'把注意力，交还此刻',tag:'专注练习',category:'focus',minutes:3,art:1,source:'original',paragraphs:[INTRO,'选一个注意力的落点，可以是鼻尖的触感，或腹部轻微的起伏。','吸气时在心里数一，呼气时数二。慢慢数到十，再从一开始，不必赶。','走神是自然的。每次发现走神，都意味着你重新看见了自己的注意力。','留意眼前一件具体的小事。结束练习后，你可以只做它的第一步。',OUTRO]},
{id:'morning',title:'给新的一天，一个温柔开场',tag:'晨间唤醒',category:'self',minutes:5,art:2,source:'original',paragraphs:[INTRO,'留意今天的光线与温度。新的一天不要求你立刻充满能量。','慢慢伸展手指，感受肩膀的状态。只在舒适范围内活动。','问问自己：今天我需要怎样照顾自己？答案可以很简单，不必宏大。','给今天选一个温柔的意图。比如更清楚地表达需要，或在忙碌时停下来喝水。','跟着几次自然的呼吸，记住这个意图。它可以陪你开始今天。',OUTRO]},
{id:'night',title:'心事，也可以明天再想',tag:'夜间安放',category:'sleep',minutes:10,art:0,source:'original',paragraphs:[INTRO,'留意今晚身体的状态。也许有些疲惫，也许思绪仍然活跃。它们都可以存在。','想象把今天的待办轻轻写在一张纸上。你可以先把这张纸放在一旁。','此刻无需得出答案，只是让身体得到一点休息。感受地面或床铺的支撑。','念头出现时，试着用一句话回应：现在是休息的时间。然后回到呼吸。','安静地停留一会儿。不必用力放空，只是感受呼吸来来回回。',OUTRO]}];
const quotes=['不必急着盛开，\n你有属于自己的时节。','我可以慢一点，\n也依然在好好向前。','此刻的我，\n值得一份温柔的照顾。','不必解决所有心事，\n先陪自己安静一会儿。','一次呼吸，\n就是一次重新开始。'];let qi=0,filter='all',meTab='custom';let current=null,playing=false,elapsed=0,timer=null,lastSegment=-1,repeat=false,voiceOn=true,ambientOn=true;let audioContext=null,master=null,modalFocus=null,requestController=null;
function format(n){return Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0')}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function openModal(html){modalFocus=document.activeElement;$('#modal-body').innerHTML=html;$('#overlay').classList.add('open');document.body.style.overflow='hidden';$('#modal-close').focus()}
function closeModal(){requestController?.abort();requestController=null;$('#overlay').classList.remove('open');document.body.style.overflow=$('#full-player').classList.contains('open')?'hidden':'';modalFocus?.focus()}
$('#modal-close').onclick=closeModal;$('#overlay').onclick=e=>{if(e.target.id==='overlay')closeModal()};document.addEventListener('keydown',e=>{const open=$('#overlay').classList.contains('open');if(e.key==='Escape'){if(open)closeModal();else closePlayer()}if(!open||e.key!=='Tab')return;const controls=[...$('#overlay').querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus()}if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus()}});
function all(){return [...practices,...state.custom]}function find(id){return all().find(p=>p.id===id)}
function artStyle(p){return `background-image:url('data:image/jpeg;base64,');background-position:${p.art===0?'0':p.art===1?'50':'100'}% 50%`}
function card(p){return `<article class="card"><div class="cover" data-play="${esc(p.id)}" role="button" tabindex="0" aria-label="播放${esc(p.title)}"><div class="art" style="${artStyle(p)}"></div><button class="heart ${state.saved.includes(p.id)?'on':''}" data-save="${esc(p.id)}" aria-label="${state.saved.includes(p.id)?'取消收藏':'收藏'}${esc(p.title)}">${state.saved.includes(p.id)?'♥':'♡'}</button><div class="cover-text"><div class="tag">${esc(p.tag||'专属冥想')}</div><h3>${esc(p.title)}</h3><div class="cover-bottom"><span class="time-pill">${p.minutes} MIN</span><button class="play-card" data-play="${esc(p.id)}" aria-label="播放">▶</button></div></div></div><div class="caption"><span>${p.source==='ai'?'AI 定制引导':p.source==='sample'?'示例练习':'原创中文引导'} · ${p.minutes} 分钟</span><span>留一点时间给自己</span></div></article>`}
function render(){ $('#home-cards').innerHTML=practices.slice(0,3).map(card).join('');$('#library-cards').innerHTML=practices.filter(p=>filter==='all'||p.category===filter).map(card).join('');$('#stat-sessions').textContent=state.sessions;$('#stat-saved').textContent=all().filter(p=>state.saved.includes(p.id)).length;$('#stat-custom').textContent=state.custom.length;const list=meTab==='custom'?state.custom:all().filter(p=>state.saved.includes(p.id));$('#history').innerHTML=list.length?list.map(p=>`<div class="history-row"><div>${esc(p.title)}<small>${p.minutes} 分钟 · ${p.source==='ai'?'AI 定制':p.source==='sample'?'明确标注的示例':'原创练习'}</small></div><button data-play="${esc(p.id)}">聆听 ▶</button></div>`).join(''):`<div class="empty">${meTab==='custom'?'从首页写下一句心事，创建第一段专属冥想。':'还没有收藏。点一下练习上的 ♡，留住喜欢的片刻。'}</div>`;$('#affirm-text').textContent=quotes[qi];if(current)$('#player-favorite').textContent=state.saved.includes(current.id)?'♥':'♡'}
function go(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));$$('.dock button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));window.scrollTo({top:0,behavior:'smooth'})}
function save(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(state.saved.includes(id)?'已收藏，随时回来听':'已取消收藏')}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav)go(nav.dataset.view);const saveButton=e.target.closest('[data-save]');if(saveButton){save(saveButton.dataset.save);return}const playButton=e.target.closest('[data-play]');if(playButton)select(find(playButton.dataset.play));const prompt=e.target.closest('[data-prompt]');if(prompt){$('#intention').value=prompt.dataset.prompt;customize(prompt.dataset.prompt)}const filterButton=e.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b===filterButton));render()}const me=e.target.closest('[data-me]');if(me){meTab=me.dataset.me;$$('[data-me]').forEach(b=>b.classList.toggle('active',b===me));render()}if(e.target.closest('[data-action="favorites"]')){meTab='saved';$$('[data-me]').forEach(b=>b.classList.toggle('active',b.dataset.me==='saved'));render();go('me')}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.cover[data-play]')){e.preventDefault();select(find(e.target.dataset.play))}});
let status={configured:false,provider:'待配置'};fetch('/api/status').then(r=>r.json()).then(s=>status=s).catch(()=>{});
$('#intention-form').onsubmit=e=>{e.preventDefault();customize($('#intention').value.trim())};
function customize(intention){openModal(`<div class="eyebrow">CREATE YOUR PERSONAL MEDITATION</div><h2 id="dialog-title">让这一段声音，为你而来。</h2><p>把此刻的需要，变成一段可以聆听的中文正念引导。</p><form id="generate-form"><label for="custom-intention">你的感受或期待</label><textarea id="custom-intention" required maxlength="500">${esc(intention)}</textarea><div class="form-cols"><div><label for="custom-name">希望如何称呼你（选填）</label><input id="custom-name" maxlength="20" placeholder="你的昵称"></div><div><label for="custom-minutes">留给自己的时间</label><select id="custom-minutes"><option value="3">3 分钟</option><option value="5" selected>5 分钟</option><option value="10">10 分钟</option></select></div></div><label for="custom-goal">今天想练习的方向</label><select id="custom-goal"><option>日常放松</option><option>睡前安放</option><option>自我关怀</option><option>专注与清晰</option></select><div class="status" style="margin-top:18px">${status.configured?'模型服务已连接 · '+esc(status.provider):'AI 服务待连接：已准备服务端接口，尚未配置模型密钥。你仍可体验单独标注的示例练习。'}</div><label class="consent"><input type="checkbox" id="consent">我同意将本次输入发送给模型服务，用于生成引导词。请勿填写敏感身份信息。</label><div id="generate-error" role="alert"></div><div class="result-actions"><button class="primary" type="submit" id="generate-button">生成我的专属冥想 ↗</button><button class="pill-btn" type="button" id="sample-button">先听一段示例</button></div></form>`);
$('#sample-button').onclick=()=>{const minutes=Number($('#custom-minutes').value);const goal=$('#custom-goal').value;const base=goal==='睡前安放'?practices[1]:goal==='自我关怀'?practices[2]:goal==='专注与清晰'?practices[3]:practices[0];showResult({...base,id:'sample-'+Date.now(),title:'体验示例 · '+base.title,minutes,source:'sample',tag:'示例体验'})};
$('#generate-form').onsubmit=async e=>{e.preventDefault();const error=$('#generate-error');if(!$('#consent').checked){error.innerHTML='<div class="error">请先确认本次生成的数据使用说明。</div>';return}if(!$('#custom-intention').value.trim())return;const body={intention:$('#custom-intention').value.trim(),name:$('#custom-name').value.trim(),minutes:Number($('#custom-minutes').value),goal:$('#custom-goal').value,consent:true};const button=$('#generate-button');button.disabled=true;$('#sample-button').disabled=true;button.innerHTML='<span class="generation-spinner"></span>正在为你写下……';error.innerHTML='';requestController=new AbortController();try{const r=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:requestController.signal});const result=await r.json();if(!r.ok)throw Error(result.error||'生成失败，请稍后重试');requestController=null;const p={...result,id:'ai-'+Date.now(),tag:'AI 专属冥想',art:body.goal==='睡前安放'?1:body.goal==='自我关怀'?2:0};state.custom.unshift(p);persist();render();showResult(p)}catch(err){if(err.name!=='AbortError'){error.innerHTML='<div class="error">'+esc(err.message)+'</div>';button.disabled=false;$('#sample-button').disabled=false;button.textContent='重新生成 ↗'}}};}
function showResult(p){openModal(`<div class="eyebrow">${p.source==='ai'?'CREATED FOR YOU · AI 生成':'SAMPLE EXPERIENCE · 示例体验'}</div><h2 id="dialog-title">${esc(p.title)}</h2><p>${p.minutes} 分钟 · ${p.source==='ai'?'根据你的输入生成，建议先阅读后聆听':'原创固定示例，未调用 AI，也未根据输入生成'}</p><div class="script">${esc(p.paragraphs.join('\n\n'))}</div><div class="result-actions"><button class="primary" id="listen-result">开始聆听 ▶</button><button class="pill-btn" id="copy-result">复制引导词</button></div>`);$('#listen-result').onclick=()=>{if(p.source==='sample'&&!state.custom.some(x=>x.id===p.id)){state.custom.unshift(p);persist();render()}closeModal();select(p)};$('#copy-result').onclick=()=>copy(p.paragraphs.join('\n\n'))}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制到剪贴板')}catch{openModal(`<h2 id="dialog-title">长按或选中文字复制</h2><textarea readonly style="height:260px">${esc(text)}</textarea>`);$('#modal-body textarea').select()}}
$('#prev-affirm').onclick=()=>{qi=(qi+quotes.length-1)%quotes.length;render()};$('#next-affirm').onclick=()=>{qi=(qi+1)%quotes.length;render()};$('#copy-affirm').onclick=()=>copy(quotes[qi]);
function openPlayer(){if(!current)return;$('#full-player').classList.add('open');document.body.style.overflow='hidden';$('#close-player').focus()}
function closePlayer(){$('#full-player').classList.remove('open');document.body.style.overflow='';$('#open-player').focus()}
$('#close-player').onclick=closePlayer;$('#open-player').onclick=openPlayer;$('#open-player').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openPlayer()}};
function select(p){if(!p)return;pause();current=p;elapsed=0;lastSegment=-1;$('#mini-player').classList.add('visible');$('#player-bg').style.backgroundImage=`linear-gradient(#27352544,#142511cc),url('data:image/jpeg;base64,')`;$('#player-bg').style.backgroundSize='cover,300% 100%';$('#player-bg').style.backgroundPosition=`center,${p.art===0?0:p.art===1?50:100}% center`;update();openPlayer();start()}
function segment(){if(!current)return 0;return Math.min(current.paragraphs.length-1,Math.floor(elapsed/(current.minutes*60/current.paragraphs.length)))}
function update(){if(!current)return;const duration=current.minutes*60;$('#player-title').textContent=current.title;$('#mini-title').textContent=current.title;$('#player-source').textContent=(current.source==='ai'?'AI 定制引导':current.source==='sample'?'示例练习 · 非 AI 生成':'原创中文引导')+' · 设备语音';$('#elapsed').textContent=format(elapsed);$('#remaining').textContent='−'+format(Math.max(0,duration-elapsed));$('#mini-time').textContent=format(elapsed)+' / '+format(duration);$('#progress').max=duration;$('#progress').value=elapsed;$('#big-play').textContent=$('#mini-play').textContent=playing?'Ⅱ':'▶';$('#big-play').setAttribute('aria-label',playing?'暂停':'播放');$('#mini-play').setAttribute('aria-label',playing?'暂停':'播放');$('#player-favorite').textContent=state.saved.includes(current.id)?'♥':'♡';$('#player-phrase').textContent=current.paragraphs[segment()];}
function ambient(){try{if(!audioContext){audioContext=new(window.AudioContext||window.webkitAudioContext)();master=audioContext.createGain();master.gain.value=0;master.connect(audioContext.destination);[130.81,196,261.63].forEach((frequency,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=frequency;g.gain.value=[.035,.018,.009][i];o.connect(g);g.connect(master);o.start()})}audioContext.resume();master.gain.setTargetAtTime(ambientOn?.7:0,audioContext.currentTime,.3)}catch{toast('当前设备无法播放底音，可继续阅读引导词')}}
function speak(){const i=segment();if(i===lastSegment)return;lastSegment=i;if(!voiceOn||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(current.paragraphs[i]);u.lang='zh-CN';u.rate=.8;const voices=window.speechSynthesis.getVoices();const v=voices.find(v=>v.voiceURI===voiceChoice)||voices.find(v=>v.lang.startsWith('zh'));if(v)u.voice=v;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('设备语音暂不可用，可跟随屏幕阅读练习')};window.speechSynthesis.speak(u)}
function start(){if(!current)return;if(elapsed>=current.minutes*60)elapsed=0;playing=true;ambient();speak();clearInterval(timer);timer=setInterval(()=>{elapsed++;if(elapsed>=current.minutes*60){state.sessions++;persist();render();if(repeat){elapsed=0;lastSegment=-1;speak()}else{pause();toast('练习完成。谢谢你把这段时间留给自己。')}}else speak();update()},1000);update()}
function pause(){playing=false;clearInterval(timer);if('speechSynthesis'in window)window.speechSynthesis.cancel();if(master)master.gain.setTargetAtTime(0,audioContext.currentTime,.3);lastSegment=-1;update()}
function toggle(){playing?pause():start()}$('#mini-play').onclick=toggle;$('#big-play').onclick=toggle;$('#mini-close').onclick=()=>{pause();$('#mini-player').classList.remove('visible')};function seek(n){if(!current)return;elapsed=Math.min(current.minutes*60-1,Math.max(0,n));lastSegment=-1;if(playing)speak();update()}$('#back').onclick=()=>seek(elapsed-10);$('#forward').onclick=()=>seek(elapsed+10);$('#progress').oninput=e=>seek(Number(e.target.value));$('#repeat').onclick=()=>{repeat=!repeat;$('#repeat').setAttribute('aria-pressed',repeat);$('#repeat').style.opacity=repeat?'1':'.5';toast(repeat?'循环播放已开启':'循环播放已关闭')};$('#ambient-toggle').onclick=()=>{ambientOn=!ambientOn;$('#ambient-toggle').setAttribute('aria-pressed',ambientOn);$('#ambient-toggle').style.opacity=ambientOn?'1':'.5';if(master)master.gain.setTargetAtTime(ambientOn&&playing?.7:0,audioContext.currentTime,.3)};$('#voice-toggle').onclick=()=>{voiceOn=!voiceOn;$('#voice-toggle').textContent=voiceOn?'人声已开启':'人声已关闭';$('#voice-toggle').setAttribute('aria-pressed',voiceOn);if(!voiceOn&&'speechSynthesis'in window)window.speechSynthesis.cancel();lastSegment=-1;if(playing&&voiceOn)speak()};$('#player-favorite').onclick=()=>{if(current)save(current.id)};$('#read-script').onclick=()=>{if(current)openModal(`<div class="eyebrow">YOUR MEDITATION SCRIPT</div><h2 id="dialog-title">${esc(current.title)}</h2><p>${current.source==='ai'?'AI 生成内容':'原创引导词'} · 段落之间可以安静停留</p><div class="script">${esc(current.paragraphs.join('\n\n'))}</div>`)};$('#copy-script').onclick=()=>{if(current)copy(current.paragraphs.join('\n\n'))};
let voiceChoice='';$('#voice-settings').onclick=()=>{const voices='speechSynthesis'in window?window.speechSynthesis.getVoices().filter(v=>v.lang.startsWith('zh')):[];openModal(`<div class="eyebrow">CHOOSE YOUR VOICE</div><h2 id="dialog-title">选一份听着舒服的陪伴。</h2><p>使用设备浏览器提供的中文语音，不同设备的声音与可用性可能不同。没有中文声音时，可以阅读引导词，配合环境底音练习。</p><label for="voice-choice">中文声音</label><select id="voice-choice"><option value="">设备默认中文声音</option>${voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)}</option>`).join('')}</select><button class="primary" id="save-voice">使用这个声音</button>`);$('#voice-choice').value=voiceChoice;$('#save-voice').onclick=()=>{voiceChoice=$('#voice-choice').value;closeModal();toast('声音已更新');lastSegment=-1;if(playing)speak()}};
let breathTimer=null,breathSeconds=0;$('#breath-start').onclick=()=>{if(breathTimer){stopBreath();return}breathSeconds=0;$('#breath-orb').classList.add('running');$('#breath-orb').textContent='吸气';$('#breath-start').textContent='结束练习';$('#breath-hint').textContent='自然呼吸，无需屏息 · 60 秒';breathTimer=setInterval(()=>{breathSeconds++;$('#breath-orb').textContent=breathSeconds%8<4?'吸气':'呼气';$('#breath-hint').textContent='自然呼吸，无需屏息 · '+(60-breathSeconds)+' 秒';if(breathSeconds>=60){stopBreath();state.sessions++;persist();render();toast('一分钟完成，带着这份安静继续吧')}},1000)};function stopBreath(){clearInterval(breathTimer);breathTimer=null;$('#breath-orb').classList.remove('running');$('#breath-orb').textContent='呼吸';$('#breath-start').textContent='开始一分钟练习 ↗';$('#breath-hint').textContent='不用做得更好，只要回到当下。'}
$('#clear-data').onclick=()=>{openModal('<h2 id="dialog-title">清除本机记录？</h2><p>将删除收藏、专属引导词与完成次数。此操作无法恢复。</p><button class="primary" id="confirm-clear">确认清除</button>');$('#confirm-clear').onclick=()=>{pause();current=null;state={saved:[],custom:[],sessions:0};persist();render();$('#mini-player').classList.remove('visible');closeModal();toast('本机记录已清除')}};
$('#privacy').onclick=()=>openModal('<div class="eyebrow">PRIVACY & GENERATION</div><h2 id="dialog-title">让陪伴，清晰而安心。</h2><p>栖心 Flow 是独立创作的中文正念网页，与 Stella 无关联。示例与预设练习均为原创固定内容，只有成功调用模型服务返回的内容才标记为「AI 定制」。</p><p>AI 生成前，需要你同意把本次感受、昵称、方向与时长发送到站点所配置的模型服务。站点程序不写入服务器数据库，模型服务和托管平台可能依各自政策处理请求及日志。请避免填写敏感身份信息。</p><p>收藏、生成结果和练习次数保存在本机浏览器。可在「我的」清除。设备语音服务由浏览器或系统提供，处理方式取决于设备设置。</p><p>这是产品体验版本，尚无账号或付费功能。本产品用于日常正念放松，不提供诊断、治疗或现实结果保证。</p>');
window.addEventListener('pagehide',()=>{pause();stopBreath()});render();
